"""Linked List Cycle II — Floyd's algorithm, phase two.

After the pointers meet, the distance from the head to the cycle entrance equals
the distance from the meeting point to it, so two one-step walkers converge
exactly on the entrance.

Time: O(n)   Space: O(1)
"""
if "ListNode" not in globals():
    class ListNode:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next


class Solution:
    def detectCycle(self, head):
        slow = fast = head
        while fast and fast.next:
            slow = slow.next
            fast = fast.next.next
            if slow is fast:
                walker = head
                while walker is not slow:
                    walker = walker.next
                    slow = slow.next
                return walker
        return None
